import{_ as a,o as t,c as n,ag as o}from"./chunks/framework.DXGyWiRo.js";const p=JSON.parse('{"title":"Channel Bugs Fix Plan","description":"","frontmatter":{},"headers":[],"relativePath":"internal/CHANNEL_BUGS_FIX_PLAN.md","filePath":"internal/CHANNEL_BUGS_FIX_PLAN.md","lastUpdated":1777882948000}'),l={name:"internal/CHANNEL_BUGS_FIX_PLAN.md"};function i(s,e,r,d,c,h){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="channel-bugs-fix-plan" tabindex="-1">Channel Bugs Fix Plan <a class="header-anchor" href="#channel-bugs-fix-plan" aria-label="Permalink to &quot;Channel Bugs Fix Plan&quot;">​</a></h1><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>This plan addresses 6 bugs/missing features related to channel management and messaging in RustChat.</p><hr><h2 id="bug-1-channel-update-delete-by-creator" tabindex="-1">Bug 1: Channel Update/Delete by Creator <a class="header-anchor" href="#bug-1-channel-update-delete-by-creator" aria-label="Permalink to &quot;Bug 1: Channel Update/Delete by Creator&quot;">​</a></h2><h3 id="current-state" tabindex="-1">Current State <a class="header-anchor" href="#current-state" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li>Channels can be created but not renamed or deleted by their creator</li><li>Backend has <code>PUT /channels/{id}</code> endpoint but only allows updating <code>display_name</code>, <code>purpose</code>, <code>header</code></li><li><code>ChannelUpdated</code> and <code>ChannelDeleted</code> WebSocket events are defined but never broadcast</li><li>No UI for editing channel name/description</li></ul><h3 id="root-causes" tabindex="-1">Root Causes <a class="header-anchor" href="#root-causes" aria-label="Permalink to &quot;Root Causes&quot;">​</a></h3><ol><li>Backend update endpoint doesn&#39;t allow changing <code>name</code> field</li><li>No permission check specifically for channel creator</li><li>WebSocket events not broadcast after update/delete operations</li><li>Frontend lacks channel settings/edit UI</li></ol><h3 id="implementation-tasks" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="backend-tasks" tabindex="-1">Backend Tasks <a class="header-anchor" href="#backend-tasks" aria-label="Permalink to &quot;Backend Tasks&quot;">​</a></h4><ol><li><p><strong>Update Channel Update Endpoint</strong> (<code>backend/src/api/channels.rs</code> and <code>backend/src/api/v4/channels/crud.rs</code>)</p><ul><li>Allow updating <code>name</code> field</li><li>Add permission check: creator OR channel admin OR team admin</li><li>Broadcast <code>ChannelUpdated</code> WebSocket event after successful update</li></ul></li><li><p><strong>Add Channel Delete Endpoint</strong> (<code>backend/src/api/channels.rs</code>)</p><ul><li>Add <code>DELETE /channels/{id}</code> endpoint (native API)</li><li>Soft delete (set <code>deleted_at</code> timestamp)</li><li>Permission check: creator OR channel admin OR team admin</li><li>Broadcast <code>ChannelDeleted</code> WebSocket event</li></ul></li><li><p><strong>Update WebSocket Broadcast</strong> (<code>backend/src/api/v4/channels/crud.rs</code>)</p><ul><li>Add <code>ChannelUpdated</code> broadcast in <code>update_channel</code> and <code>patch_channel</code> handlers</li><li>Add <code>ChannelDeleted</code> broadcast in <code>delete_channel</code> handler</li></ul></li></ol><h4 id="frontend-tasks" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol start="4"><li><p><strong>Add Channel Edit UI</strong> (<code>frontend/src/components/channels/</code>)</p><ul><li>Create <code>EditChannelModal.vue</code> component</li><li>Form fields: name, display_name, purpose/description</li><li>Validation for name (lowercase, no spaces)</li></ul></li><li><p><strong>Update Channel Context Menu</strong> (<code>frontend/src/components/channels/ChannelContextMenu.vue</code>)</p><ul><li>Add &quot;Edit Channel&quot; option for channel creator/admins</li><li>Add &quot;Delete Channel&quot; option with confirmation dialog</li></ul></li><li><p><strong>Add Channel Service Methods</strong> (<code>frontend/src/features/channels/services/channelService.ts</code>)</p><ul><li><code>updateChannel(channelId, data)</code> method</li><li><code>deleteChannel(channelId)</code> method</li><li>Handle WebSocket events for channel updates</li></ul></li><li><p><strong>Handle WebSocket Events</strong> (<code>frontend/src/core/websocket/registerHandlers.ts</code>)</p><ul><li>Add handler for <code>channel_updated</code> event</li><li>Add handler for <code>channel_deleted</code> event</li><li>Update channel store when events received</li></ul></li></ol><hr><h2 id="bug-2-real-time-message-deletion" tabindex="-1">Bug 2: Real-time Message Deletion <a class="header-anchor" href="#bug-2-real-time-message-deletion" aria-label="Permalink to &quot;Bug 2: Real-time Message Deletion&quot;">​</a></h2><h3 id="current-state-1" tabindex="-1">Current State <a class="header-anchor" href="#current-state-1" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li>Backend broadcasts <code>post_deleted</code> WebSocket event</li><li>Frontend has handler registered in <code>registerHandlers.ts</code></li><li>Message is removed from store via <code>handleMessageDelete</code></li></ul><h3 id="root-cause-analysis" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h3><p>Based on code review, the implementation looks correct. The issue might be:</p><ol><li>WebSocket event not being received by all users</li><li>Event payload structure mismatch</li><li>Handler not processing the event correctly</li></ol><h3 id="implementation-tasks-1" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks-1" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="verification-tasks" tabindex="-1">Verification Tasks <a class="header-anchor" href="#verification-tasks" aria-label="Permalink to &quot;Verification Tasks&quot;">​</a></h4><ol><li><p><strong>Verify WebSocket Broadcast</strong> (<code>backend/src/api/posts.rs</code> and <code>backend/src/api/v4/posts.rs</code>)</p><ul><li>Confirm <code>post_deleted</code> event is broadcast to all channel members</li><li>Check broadcast <code>channel_id</code> is set correctly</li><li>Verify <code>exclude_user_id</code> is set (deleter doesn&#39;t need the event)</li></ul></li><li><p><strong>Fix WebSocket Payload Consistency</strong></p><ul><li>Native API sends: <code>{id, channel_id}</code></li><li>MM v4 API sends: full <code>deleted_post</code> object</li><li>Standardize payload to include: <code>post_id</code>, <code>channel_id</code></li></ul></li></ol><h4 id="frontend-tasks-1" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks-1" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol start="3"><li><p><strong>Verify Handler Registration</strong> (<code>frontend/src/core/websocket/registerHandlers.ts</code>)</p><ul><li>Confirm handler is properly registered for <code>post_deleted</code> event</li><li>Check that handler extracts <code>post_id</code> and <code>channel_id</code> correctly</li></ul></li><li><p><strong>Debug Message Removal</strong> (<code>frontend/src/features/messages/handlers/messageSocketHandlers.ts</code>)</p><ul><li>Ensure <code>handleMessageDelete</code> is called</li><li>Verify store&#39;s <code>removeMessage</code> correctly filters by channel AND message ID</li><li>Add logging for debugging</li></ul></li></ol><hr><h2 id="bug-3-private-channels-in-sidebar" tabindex="-1">Bug 3: Private Channels in Sidebar <a class="header-anchor" href="#bug-3-private-channels-in-sidebar" aria-label="Permalink to &quot;Bug 3: Private Channels in Sidebar&quot;">​</a></h2><h3 id="current-state-2" tabindex="-1">Current State <a class="header-anchor" href="#current-state-2" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li><code>ChannelSidebar.vue</code> shows 4 sections: Favorites, Channels (public), Private Channels, DMs</li><li>Private channels already use Lock icon</li></ul><h3 id="desired-state" tabindex="-1">Desired State <a class="header-anchor" href="#desired-state" aria-label="Permalink to &quot;Desired State&quot;">​</a></h3><ul><li>Merge private channels into the main &quot;Channels&quot; section</li><li>Keep Lock icon to distinguish private channels</li><li>Remove separate &quot;Private Channels&quot; section</li></ul><h3 id="implementation-tasks-2" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks-2" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="frontend-tasks-2" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks-2" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol><li><p><strong>Update ChannelSidebar.vue</strong> (<code>frontend/src/components/layout/ChannelSidebar.vue</code>)</p><ul><li>Remove separate &quot;Private Channels&quot; section (lines ~143-148)</li><li>Merge <code>privateChannels</code> into <code>publicChannels</code> computed property</li><li>Rename computed property to just <code>channels</code> for clarity</li><li>Keep Lock icon for private channels (already implemented)</li></ul></li><li><p><strong>Update Channel Sorting</strong></p><ul><li>Combine and sort all channels alphabetically (public + private)</li><li>Favorites should still appear at top</li></ul></li></ol><hr><h2 id="bug-4-browse-channels-not-working" tabindex="-1">Bug 4: Browse Channels Not Working <a class="header-anchor" href="#bug-4-browse-channels-not-working" aria-label="Permalink to &quot;Bug 4: Browse Channels Not Working&quot;">​</a></h2><h3 id="current-state-3" tabindex="-1">Current State <a class="header-anchor" href="#current-state-3" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li><code>BrowseChannelsModal.vue</code> exists but shows empty list</li><li>Backend endpoint exists: <code>GET /channels?team_id=&lt;id&gt;&amp;available_to_join=true</code></li></ul><h3 id="root-cause-analysis-1" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis-1" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h3><ol><li>API might not be returning public channels correctly</li><li>Frontend might not be calling API correctly</li><li>User might not be a team member (required permission)</li></ol><h3 id="implementation-tasks-3" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks-3" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="backend-tasks-1" tabindex="-1">Backend Tasks <a class="header-anchor" href="#backend-tasks-1" aria-label="Permalink to &quot;Backend Tasks&quot;">​</a></h4><ol><li><strong>Fix Browse Channels Query</strong> (<code>backend/src/api/channels.rs</code>) <ul><li>Verify SQL query returns public channels user is not member of</li><li>Check that team membership check is working correctly</li><li>Ensure <code>available_to_join=true</code> filter works for public channels</li></ul></li></ol><h4 id="frontend-tasks-3" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks-3" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol start="2"><li><p><strong>Debug API Call</strong> (<code>frontend/src/features/channels/services/channelService.ts</code>)</p><ul><li>Add logging to <code>loadJoinableChannels</code> method</li><li>Verify <code>teamId</code> is being passed correctly</li><li>Check API response handling</li></ul></li><li><p><strong>Fix BrowseChannelsModal</strong> (<code>frontend/src/components/modals/BrowseChannelsModal.vue</code>)</p><ul><li>Ensure modal calls <code>fetchJoinableChannels</code> on open</li><li>Handle empty state properly (show &quot;No channels available&quot; message)</li><li>Add loading state</li></ul></li><li><p><strong>Add Channel Type Indicator</strong></p><ul><li>Show lock icon for private channels in browse list</li><li>Show hash icon for public channels</li></ul></li></ol><hr><h2 id="bug-5-channel-bold-notifications-for-new-messages" tabindex="-1">Bug 5: Channel Bold + Notifications for New Messages <a class="header-anchor" href="#bug-5-channel-bold-notifications-for-new-messages" aria-label="Permalink to &quot;Bug 5: Channel Bold + Notifications for New Messages&quot;">​</a></h2><h3 id="current-state-4" tabindex="-1">Current State <a class="header-anchor" href="#current-state-4" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li>Channels become bold based on unread count (working)</li><li>Browser notifications only trigger on mentions (not all messages)</li></ul><h3 id="desired-state-1" tabindex="-1">Desired State <a class="header-anchor" href="#desired-state-1" aria-label="Permalink to &quot;Desired State&quot;">​</a></h3><ul><li>Channel becomes bold when new message arrives (working - verify)</li><li>Browser notifications for new messages (not just mentions)</li></ul><h3 id="implementation-tasks-4" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks-4" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="frontend-tasks-4" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks-4" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol><li><p><strong>Verify Bold Channel Names</strong> (<code>frontend/src/components/layout/ChannelSidebar.vue</code>)</p><ul><li>Check that <code>unreadCount &gt; 0</code> applies <code>font-semibold</code> class</li><li>Ensure WebSocket <code>posted</code> event increments unread count</li><li>Verify current channel doesn&#39;t show as bold</li></ul></li><li><p><strong>Fix Browser Notifications</strong> (<code>frontend/src/composables/useWebSocket.ts</code>)</p><ul><li>Currently only notifies on mentions: <code>if (mentionsUser)</code></li><li>Remove mention check to notify on all messages</li><li>Or add user preference for notification level (all vs mentions)</li><li>Notification should include channel name and message preview</li></ul></li><li><p><strong>Add Desktop Notifications Toggle</strong></p><ul><li>Add to user preferences/settings</li><li>Options: &quot;All messages&quot;, &quot;Mentions only&quot;, &quot;None&quot;</li></ul></li></ol><hr><h2 id="bug-6-composer-send-button-with-attachments" tabindex="-1">Bug 6: Composer Send Button with Attachments <a class="header-anchor" href="#bug-6-composer-send-button-with-attachments" aria-label="Permalink to &quot;Bug 6: Composer Send Button with Attachments&quot;">​</a></h2><h3 id="current-state-5" tabindex="-1">Current State <a class="header-anchor" href="#current-state-5" aria-label="Permalink to &quot;Current State&quot;">​</a></h3><ul><li><code>canSend</code> computed: <code>(hasContent || hasUploadedFiles) &amp;&amp; !hasUploadInProgress</code></li><li>User reports button is disabled after attachment upload completes</li></ul><h3 id="root-cause-analysis-2" tabindex="-1">Root Cause Analysis <a class="header-anchor" href="#root-cause-analysis-2" aria-label="Permalink to &quot;Root Cause Analysis&quot;">​</a></h3><p>The logic looks correct. The issue might be:</p><ol><li><code>uploaded</code> property not being set correctly after upload</li><li>Reactivity issue with <code>attachedFiles</code> array</li><li>Race condition between upload completion and state update</li></ol><h3 id="implementation-tasks-5" tabindex="-1">Implementation Tasks <a class="header-anchor" href="#implementation-tasks-5" aria-label="Permalink to &quot;Implementation Tasks&quot;">​</a></h3><h4 id="frontend-tasks-5" tabindex="-1">Frontend Tasks <a class="header-anchor" href="#frontend-tasks-5" aria-label="Permalink to &quot;Frontend Tasks&quot;">​</a></h4><ol><li><p><strong>Debug Upload State</strong> (<code>frontend/src/components/composer/MessageComposer.vue</code>)</p><ul><li>Add console logging to track <code>attachedFiles</code> state</li><li>Verify <code>uploaded</code> property is set after successful upload</li><li>Check that <code>uploading</code> is set to false when upload completes</li></ul></li><li><p><strong>Fix Reactivity Issue</strong></p><ul><li>Ensure <code>attachedFiles</code> array is properly reactive</li><li>Use <code>Vue.set</code> or array replacement instead of mutation if needed</li><li>Verify <code>canSend</code> computed re-evaluates when <code>attachedFiles</code> changes</li></ul></li><li><p><strong>Verify File Upload Flow</strong></p><ul><li>Check <code>handleFiles</code> method sets up upload correctly</li><li>Verify <code>onUploadProgress</code> callback updates state</li><li>Ensure error handling doesn&#39;t leave upload in stuck state</li></ul></li></ol><hr><h2 id="testing-checklist" tabindex="-1">Testing Checklist <a class="header-anchor" href="#testing-checklist" aria-label="Permalink to &quot;Testing Checklist&quot;">​</a></h2><h3 id="backend-tests" tabindex="-1">Backend Tests <a class="header-anchor" href="#backend-tests" aria-label="Permalink to &quot;Backend Tests&quot;">​</a></h3><ul><li>[ ] Channel update endpoint allows name change by creator</li><li>[ ] Channel delete endpoint soft-deletes channel</li><li>[ ] WebSocket events broadcast on channel update/delete</li><li>[ ] Browse channels returns public channels not yet joined</li><li>[ ] Message deletion broadcasts to all channel members</li></ul><h3 id="frontend-tests" tabindex="-1">Frontend Tests <a class="header-anchor" href="#frontend-tests" aria-label="Permalink to &quot;Frontend Tests&quot;">​</a></h3><ul><li>[ ] Channel creator sees Edit/Delete options in context menu</li><li>[ ] Channel edit modal updates name/description</li><li>[ ] Channel delete shows confirmation and removes channel</li><li>[ ] Private channels appear in main channels list with lock icon</li><li>[ ] Browse channels shows public channels to join</li><li>[ ] Joining channel adds it to sidebar immediately</li><li>[ ] Channel becomes bold when new message arrives</li><li>[ ] Browser notification shows for new messages</li><li>[ ] Send button enabled after attachment upload completes</li><li>[ ] Send button disabled during attachment upload</li></ul><h3 id="integration-tests" tabindex="-1">Integration Tests <a class="header-anchor" href="#integration-tests" aria-label="Permalink to &quot;Integration Tests&quot;">​</a></h3><ul><li>[ ] User A deletes message, User B sees it removed immediately</li><li>[ ] User A updates channel name, User B sees updated name</li><li>[ ] User A deletes channel, User B sees channel removed from sidebar</li></ul><hr><h2 id="files-to-modify" tabindex="-1">Files to Modify <a class="header-anchor" href="#files-to-modify" aria-label="Permalink to &quot;Files to Modify&quot;">​</a></h2><h3 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h3><ol><li><code>backend/src/api/channels.rs</code> - Update channel update, add delete endpoint</li><li><code>backend/src/api/v4/channels/crud.rs</code> - Add WebSocket broadcasts</li><li><code>backend/src/realtime/events.rs</code> - Verify event types (if needed)</li></ol><h3 id="frontend" tabindex="-1">Frontend <a class="header-anchor" href="#frontend" aria-label="Permalink to &quot;Frontend&quot;">​</a></h3><ol><li><code>frontend/src/components/channels/EditChannelModal.vue</code> - NEW FILE</li><li><code>frontend/src/components/channels/ChannelContextMenu.vue</code> - Add edit/delete options</li><li><code>frontend/src/components/layout/ChannelSidebar.vue</code> - Merge private channels</li><li><code>frontend/src/components/modals/BrowseChannelsModal.vue</code> - Fix loading/display</li><li><code>frontend/src/components/composer/MessageComposer.vue</code> - Fix send button logic</li><li><code>frontend/src/composables/useWebSocket.ts</code> - Fix notifications</li><li><code>frontend/src/core/websocket/registerHandlers.ts</code> - Add channel event handlers</li><li><code>frontend/src/features/channels/services/channelService.ts</code> - Add update/delete methods</li><li><code>frontend/src/features/channels/stores/channelStore.ts</code> - Handle channel updates</li></ol><hr><h2 id="estimated-effort" tabindex="-1">Estimated Effort <a class="header-anchor" href="#estimated-effort" aria-label="Permalink to &quot;Estimated Effort&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Bug</th><th>Backend</th><th>Frontend</th><th>Total</th></tr></thead><tbody><tr><td>1. Channel update/delete</td><td>4h</td><td>6h</td><td>10h</td></tr><tr><td>2. Message deletion realtime</td><td>1h</td><td>1h</td><td>2h</td></tr><tr><td>3. Private channels sidebar</td><td>0h</td><td>1h</td><td>1h</td></tr><tr><td>4. Browse channels</td><td>1h</td><td>2h</td><td>3h</td></tr><tr><td>5. Channel bold + notifications</td><td>0h</td><td>2h</td><td>2h</td></tr><tr><td>6. Composer send button</td><td>0h</td><td>2h</td><td>2h</td></tr><tr><td><strong>Total</strong></td><td><strong>6h</strong></td><td><strong>14h</strong></td><td><strong>20h</strong></td></tr></tbody></table><hr><h2 id="priority-order" tabindex="-1">Priority Order <a class="header-anchor" href="#priority-order" aria-label="Permalink to &quot;Priority Order&quot;">​</a></h2><ol><li><strong>Bug 6</strong> - Composer send button (critical usability issue)</li><li><strong>Bug 3</strong> - Private channels sidebar (simple UI change)</li><li><strong>Bug 2</strong> - Message deletion realtime (verify/fix existing code)</li><li><strong>Bug 4</strong> - Browse channels (medium complexity)</li><li><strong>Bug 5</strong> - Channel notifications (medium complexity)</li><li><strong>Bug 1</strong> - Channel update/delete (highest complexity)</li></ol>',85)])])}const m=a(l,[["render",i]]);export{p as __pageData,m as default};
